import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useStore } from '../../store/useStore';
import { generateVivaQuestions, gradeVivaAnswer, gradeVivaSession, groqChat } from '../../utils/aiService';
import { apiPost, apiGet } from '../../utils/api';

var API = 'http://localhost:5000/api';
function getToken() { return localStorage.getItem('examai_token'); }
var SESSION_KEY = 'dexam_viva_session';
var SR = window.SpeechRecognition || window.webkitSpeechRecognition;

function restoreSession() {
  try { return JSON.parse(sessionStorage.getItem(SESSION_KEY) || 'null'); } catch(e) { return null; }
}

async function gradeAnswer(question, modelAnswer, studentAnswer) {
  if (!studentAnswer || !studentAnswer.trim()) {
    return { correct: false, score_pct: 0, verdict: 'No Answer', feedback: 'Student did not provide an answer.', missing: modelAnswer };
  }
  try {
    var sys = 'You are a strict viva examiner. Return ONLY valid JSON.';
    var usr = 'Question: ' + question + '\nModel Answer: ' + modelAnswer + '\nStudent Answer: ' + studentAnswer +
      '\nReturn: {"correct":bool,"score_pct":0-100,"verdict":"Correct|Partially Correct|Incorrect","feedback":"2-3 sentences","missing":"key point missed or None"}';
    var raw = await groqChat(sys, usr, 400, 0.2);
    return JSON.parse(raw.replace(/```json|```/g,'').trim());
  } catch(e) {
    return { correct: false, score_pct: 0, verdict: 'Error', feedback: 'Grading failed: ' + e.message, missing: '' };
  }
}

export default function VivaRoom() {
  var store = useStore();
  var _restore = restoreSession();

  var [phase,      setPhase]      = useState(_restore ? 'room' : 'setup');
  var [title,      setTitle]      = useState(_restore ? _restore.title : '');
  var [topic,      setTopic]      = useState(_restore ? _restore.topic : '');
  var savedVivaRef = useRef(_restore || null);

  // Questions & session state
  var [questions,       setQuestions]       = useState([]);
  var [currentQ,        setCurrentQ]        = useState(0);
  var [transcript,      setTranscript]      = useState([]);
  var [loading,         setLoading]         = useState(false);

  // Speech: TTS (admin reads question) + STT (student answers)
  var [speaking,        setSpeaking]        = useState(false);  // TTS active
  var [listening,       setListening]       = useState(false);  // STT active
  var [liveTranscript,  setLiveTranscript]  = useState('');     // current STT text
  var [interimText,     setInterimText]     = useState('');     // interim STT words
  var [capturedAnswer,  setCapturedAnswer]  = useState('');     // finalized student answer
  var [examinerNotes,   setExaminerNotes]   = useState('');
  var [verdict,         setVerdict]         = useState(null);
  var [verdicting,      setVerdicting]      = useState(false);
  var [srSupport,       setSrSupport]       = useState(false);
  var [ttsSupport,      setTtsSupport]      = useState(false);

  var recRef   = useRef(null);
  var synthRef = useRef(window.speechSynthesis);
  var liveRef  = useRef(''); // always-fresh transcript for intervals

  // Generator
  var [genTopic,  setGenTopic]  = useState('');
  var [genCount,  setGenCount]  = useState(5);

  // Custom question
  var [showCustomQ,    setShowCustomQ]    = useState(false);
  var [customQuestion, setCustomQuestion] = useState('');
  var [customModelAns, setCustomModelAns] = useState('');
  var [genModel,       setGenModel]       = useState(false);

  // Invite
  var [showInvite,  setShowInvite]  = useState(false);
  var [inviteMode,  setInviteMode]  = useState('account');
  var [inviteEmail, setInviteEmail] = useState('');
  var [students,    setStudents]    = useState([]);
  var [selectedStu, setSelectedStu] = useState([]);
  var [inviteMsg,   setInviteMsg]   = useState('');
  var [inviting,    setInviting]    = useState(false);

  // Alerts
  var [alerts,     setAlerts]     = useState([]);
  var [unread,     setUnread]     = useState(0);
  var [showAlerts, setShowAlerts] = useState(false);
  var alertLastRef = useRef(Date.now());
  var pollRef      = useRef(null);

  // Examiner away
  var [examinerAway,   setExaminerAway]   = useState(false);
  var [awayCountdown,  setAwayCountdown]  = useState(600);
  var [examinerLocked, setExaminerLocked] = useState(false);
  var awayTimerRef = useRef(null);
  var awayStartRef = useRef(null);
  var graceRef     = useRef(null);

  // Results
  var [results,        setResults]        = useState(null);
  var [editableAnswers,setEditableAnswers]= useState([]);
  var [finalizing,     setFinalizing]     = useState(false);

  // Camera
  var adminVid  = useRef(null);
  var streamRef = useRef(null);

  useEffect(function() {
    setSrSupport(!!SR);
    setTtsSupport(!!(window.speechSynthesis));
    if (_restore && _restore.viva_id) { setTimeout(startMedia, 400); startPolling(); }
    return function() { stopAll(); };
  }, []); // eslint-disable-line

  // Away detection — only visibilitychange
  useEffect(function() {
    if (phase !== 'room') return;
    function onVisChange() {
      if (document.hidden && !examinerAway && !examinerLocked) {
        graceRef.current = setTimeout(function() {
          if (document.hidden) { setExaminerAway(true); awayStartRef.current = Date.now(); setAwayCountdown(600); }
        }, 4000);
      } else if (!document.hidden) { clearTimeout(graceRef.current); }
    }
    document.addEventListener('visibilitychange', onVisChange);
    return function() { document.removeEventListener('visibilitychange', onVisChange); clearTimeout(graceRef.current); };
  }, [phase, examinerAway, examinerLocked]); // eslint-disable-line

  useEffect(function() {
    if (!examinerAway) { clearInterval(awayTimerRef.current); return; }
    awayTimerRef.current = setInterval(function() {
      var remaining = 600 - Math.floor((Date.now() - awayStartRef.current) / 1000);
      if (remaining <= 0) {
        clearInterval(awayTimerRef.current); setExaminerAway(false); setExaminerLocked(true);
        sessionStorage.removeItem(SESSION_KEY);
        var vid = savedVivaRef.current ? savedVivaRef.current.viva_id : null;
        if (vid) fetch(API+'/viva/'+vid+'/lock',{ method:'POST', headers:{'Content-Type':'application/json',Authorization:'Bearer '+getToken()}, body:JSON.stringify({locked:true}) }).catch(function(){});
      } else { setAwayCountdown(remaining); }
    }, 1000);
    return function() { clearInterval(awayTimerRef.current); };
  }, [examinerAway]); // eslint-disable-line

  function examinerReturn() {
    clearInterval(awayTimerRef.current); clearTimeout(graceRef.current);
    setExaminerAway(false); setAwayCountdown(600); awayStartRef.current = null;
    setTimeout(function() { if (adminVid.current && streamRef.current) adminVid.current.srcObject = streamRef.current; }, 200);
  }

  function startPolling() {
    alertLastRef.current = Date.now(); clearInterval(pollRef.current);
    pollRef.current = setInterval(async function() {
      try {
        var notifs = await apiGet('/notifications');
        var fresh = (notifs||[]).filter(function(n) {
          return new Date(n.created_at||0).getTime() > alertLastRef.current &&
            n.title && (n.title.includes('Left Viva')||n.title.includes('Returned')||n.title.includes('Removed')||n.title.includes('INTEGRITY'));
        });
        if (fresh.length > 0) { alertLastRef.current = Date.now(); setAlerts(function(p){return fresh.concat(p).slice(0,40);}); setUnread(function(p){return p+fresh.length;}); }
      } catch(e) {}
    }, 6000);
  }

  async function handleStartRoom() {
    if (!title.trim()) return;
    setLoading(true);
    try {
      var r = await apiPost('/viva', { title, topic, questions:[] });
      var vivaData = { viva_id: r.viva_id, title, topic };
      savedVivaRef.current = vivaData;
      sessionStorage.setItem(SESSION_KEY, JSON.stringify(vivaData));
      setPhase('room'); setTimeout(startMedia, 300); startPolling();
    } catch(e) { alert(e.message); }
    setLoading(false);
  }

  function startMedia() {
    navigator.mediaDevices.getUserMedia({ video:true, audio:true }).then(function(stream) {
      streamRef.current = stream;
      var iv = setInterval(function(){ if (adminVid.current) { adminVid.current.srcObject = stream; clearInterval(iv); } }, 200);
    }).catch(function(){});
  }

  function stopAll() {
    clearInterval(pollRef.current); clearInterval(awayTimerRef.current); clearTimeout(graceRef.current);
    stopListening(); synthRef.current && synthRef.current.cancel();
    if (streamRef.current) streamRef.current.getTracks().forEach(function(t){t.stop();});
  }

  // ── TTS: read question aloud ──────────────────────────────
  function speakQuestion(text) {
    if (!ttsSupport || !text) return;
    synthRef.current.cancel();
    var utt = new SpeechSynthesisUtterance(text);
    utt.rate = 0.88; utt.pitch = 1;
    utt.onstart = function() { setSpeaking(true); };
    utt.onend   = function() { setSpeaking(false); };
    synthRef.current.speak(utt);
    setSpeaking(true);
  }

  // ── STT: capture student's spoken answer ──────────────────
  function startListening() {
    if (!SR) { store.addToast('Speech recognition requires Chrome or Edge', 'error'); return; }
    stopListening();
    var rec = new SR();
    rec.continuous     = true;
    rec.interimResults = true;
    rec.lang           = 'en-US';
    rec.onresult = function(e) {
      var finalPart = '', interimPart = '';
      for (var i = e.resultIndex; i < e.results.length; i++) {
        if (e.results[i].isFinal) finalPart += e.results[i][0].transcript + ' ';
        else interimPart += e.results[i][0].transcript;
      }
      if (finalPart) {
        setLiveTranscript(function(p) { var next = p + finalPart; liveRef.current = next; return next; });
      }
      setInterimText(interimPart);
    };
    rec.onerror = function(e) { if (e.error !== 'no-speech') store.addToast('Mic error: ' + e.error, 'error'); };
    rec.onend   = function() { if (recRef.current) { try { rec.start(); } catch(e){} } };
    rec.start();
    recRef.current = rec;
    setListening(true);
  }

  function stopListening() {
    if (recRef.current) { try { recRef.current.stop(); } catch(e){} recRef.current = null; }
    setListening(false); setInterimText('');
    // Capture whatever was transcribed
    if (liveRef.current.trim()) setCapturedAnswer(function(p) { return p + (p ? ' ' : '') + liveRef.current.trim(); });
    liveRef.current = '';
    setLiveTranscript('');
  }

  function clearAnswer() {
    setCapturedAnswer(''); setLiveTranscript(''); setInterimText('');
    liveRef.current = ''; setVerdict(null);
  }

  // ── Grade current answer ──────────────────────────────────
  async function handleGrade() {
    var ans = capturedAnswer || liveTranscript;
    if (!ans.trim() || !questions[currentQ]) return;
    setVerdicting(true);
    var q = questions[currentQ];
    var v = await gradeAnswer(q.question, q.model_answer, ans);
    setVerdict(v);
    setVerdicting(false);
  }

  // ── Save & move to next question ─────────────────────────
  function handleSaveNext() {
    var q   = questions[currentQ];
    var ans = capturedAnswer || liveTranscript;
    var entry = {
      question:       q.question,
      model_answer:   q.model_answer,
      student_answer: ans,
      notes:          examinerNotes,
      verdict:        verdict,
      _custom:        q._custom || false,
    };
    setTranscript(function(t){ return t.concat([entry]); });
    // Reset for next question
    setCapturedAnswer(''); setLiveTranscript(''); liveRef.current = '';
    setInterimText(''); setExaminerNotes(''); setVerdict(null);
    // Auto-advance and speak next question
    if (currentQ < questions.length - 1) {
      var nextIdx = currentQ + 1;
      setCurrentQ(nextIdx);
      setTimeout(function() { speakQuestion(questions[nextIdx].question); }, 500);
    }
  }

  // ── Generate questions (append, never replace) ────────────
  async function handleGenerateQ() {
    if (!genTopic.trim()) return;
    setLoading(true);
    try {
      var existing = questions.map(function(q){ return q.question || ''; });
      var newQs = await generateVivaQuestions(genTopic, genCount, existing);
      setQuestions(function(prev) { return prev.concat(newQs); });
    } catch(e) { alert('Generation failed: ' + e.message); }
    setLoading(false);
  }

  // ── Add examiner's own question ───────────────────────────
  async function handleAddCustomQuestion() {
    if (!customQuestion.trim()) return;
    var modelAns = customModelAns.trim();
    if (!modelAns) {
      setGenModel(true);
      try {
        var raw = await groqChat(
          'You are a subject expert. Give a clear, detailed model answer.',
          'Provide a 3-5 sentence model answer for this viva question: ' + customQuestion,
          300, 0.5
        );
        modelAns = raw;
      } catch(e) { modelAns = '(Model answer not available)'; }
      setGenModel(false);
    }
    setQuestions(function(prev){ return prev.concat([{ question: customQuestion, model_answer: modelAns, _custom: true }]); });
    setCustomQuestion(''); setCustomModelAns(''); setShowCustomQ(false);
  }

  // ── End viva: grade all, build full transcript ────────────
  async function handleEndGrade() {
    stopAll();
    sessionStorage.removeItem(SESSION_KEY);
    setLoading(true); setPhase('grading');
    try {
      // Grade each entry
      var graded = [];
      for (var i = 0; i < transcript.length; i++) {
        var t = transcript[i];
        var v2 = t.verdict || await gradeAnswer(t.question, t.model_answer, t.student_answer);
        graded.push(Object.assign({}, t, { verdict_obj: v2, correct: v2.correct, score_pct: v2.score_pct, ai_feedback: v2.feedback, ai_verdict: v2.verdict, missing: v2.missing }));
      }

      // Overall session report via Groq
      var tText = graded.map(function(t,i){
        return 'Q'+(i+1)+(t._custom?' [Examiner Q]':'')+': '+t.question+
          '\nStudent: '+t.student_answer+'\nModel: '+t.model_answer;
      }).join('\n\n');
      var report = await gradeVivaSession(tText);

      var edited = graded.map(function(t,i){
        var ra = (report.answers && report.answers[i]) || {};
        return {
          question: t.question, model_answer: t.model_answer, student_answer: t.student_answer,
          notes: t.notes||'', _custom: t._custom||false,
          verdict:   t.ai_verdict  || ra.verdict  || 'Not graded',
          score_pct: t.score_pct   || ra.score    || 0,
          feedback:  t.ai_feedback || ra.feedback || '',
          correct:   t.correct     || ra.correct  || false,
          missing:   t.missing     || '',
        };
      });

      setEditableAnswers(edited); setResults(report);
      var vivaId = savedVivaRef.current ? savedVivaRef.current.viva_id : null;
      if (vivaId) await apiPost('/viva/'+vivaId+'/end', { ended: true });
      setPhase('results');
    } catch(e) { alert('Grading failed: ' + e.message); setPhase('room'); }
    setLoading(false);
  }

  function updateAnswer(idx, field, val) {
    setEditableAnswers(function(prev) {
      var arr = prev.slice(); arr[idx] = Object.assign({}, arr[idx]); arr[idx][field] = val;
      if (field === 'verdict') { arr[idx].correct = val === 'Correct'; arr[idx].score_pct = val==='Correct'?100:val==='Partially Correct'?50:0; }
      return arr;
    });
  }

  async function handleFinalize() {
    setFinalizing(true);
    var totalScore = editableAnswers.length > 0
      ? Math.round(editableAnswers.reduce(function(a,e){ return a+(Number(e.score_pct)||0); },0)/editableAnswers.length) : 0;
    var grade = totalScore>=90?'A+':totalScore>=80?'A':totalScore>=70?'B':totalScore>=60?'C':totalScore>=50?'D':'F';
    var correctCount = editableAnswers.filter(function(e){ return e.correct; }).length;
    var fullTranscript = editableAnswers.map(function(e,i){
      return '━━━ Q'+(i+1)+(e._custom?' [Examiner\'s Question]':'')+' ━━━'+
        '\nQuestion: '+e.question+
        '\nModel Answer: '+e.model_answer+
        '\nStudent Answer: '+e.student_answer+
        '\nVerdict: '+e.verdict+' ('+e.score_pct+'%)'+
        '\nFeedback: '+e.feedback+
        (e.missing&&e.missing!=='None'?'\nMissing: '+e.missing:'')+
        (e.notes?'\nExaminer Notes: '+e.notes:'');
    }).join('\n\n');
    try {
      var vivaId = savedVivaRef.current ? savedVivaRef.current.viva_id : null;
      if (vivaId) await apiPost('/viva/'+vivaId+'/result', {
        total_score: totalScore, grade, correct_count: correctCount,
        full_transcript: fullTranscript,
        ai_report: Object.assign({}, results, { answers:editableAnswers, total_score:totalScore, grade }),
      });
      setResults(function(r){ return Object.assign({}, r, { total_score:totalScore, grade, correct_count:correctCount }); });
      savedVivaRef.current = null; setPhase('final');
    } catch(e) { alert('Save failed: ' + e.message); }
    setFinalizing(false);
  }

  function copyRoomId() { navigator.clipboard.writeText(savedVivaRef.current?savedVivaRef.current.viva_id:'').then(function(){alert('Copied!');}); }
  async function loadStudents() { try { setStudents((await apiGet('/students'))||[]); } catch(e){} }
  function toggleStudent(id) { setSelectedStu(function(p){ return p.includes(id)?p.filter(function(x){return x!==id;}):p.concat([id]); }); }
  async function sendInvites() {
    var vivaId = savedVivaRef.current ? savedVivaRef.current.viva_id : null;
    if (!vivaId) { alert('No room yet'); return; }
    setInviting(true); setInviteMsg('');
    try {
      if (inviteMode==='account' && selectedStu.length>0) {
        var n=0;
        for (var i=0;i<selectedStu.length;i++) { var s=students.find(function(x){return x.user_id===selectedStu[i];}); if(s){await apiPost('/notifications',{title:'Viva Invitation — '+title,message:'Invited to "'+title+'". Room: '+vivaId,type:'info',recipient_id:s.user_id,viva_room_id:vivaId});n++;} }
        setInviteMsg('Sent to '+n+' student(s).'); setSelectedStu([]);
      } else if (inviteMode==='email' && inviteEmail.trim()) {
        await apiPost('/viva/invite',{emails:inviteEmail.split(',').map(function(e){return e.trim();}),title,topic,vivaId});
        setInviteMsg('Emails sent!'); setInviteEmail('');
      }
    } catch(e) { setInviteMsg('Error: '+e.message); }
    setInviting(false);
  }

  function resetAll() {
    sessionStorage.removeItem(SESSION_KEY); stopAll();
    setPhase('setup'); setResults(null); setTranscript([]); setQuestions([]); setEditableAnswers([]);
    savedVivaRef.current=null; setTitle(''); setTopic(''); setExaminerLocked(false); setExaminerAway(false);
    setCapturedAnswer(''); setLiveTranscript(''); setVerdict(null); setCurrentQ(0);
  }

  // ════ SETUP ════════════════════════════════════════════════
  if (phase==='setup') return (
    <div className="viva-dark fade-up">
      <div style={{maxWidth:520,margin:'60px auto',textAlign:'center'}}>
        <div style={{fontSize:'3rem',marginBottom:16}}>🎙</div>
        <div style={{fontFamily:'Space Grotesk,sans-serif',fontWeight:800,fontSize:'1.6rem',color:'#fff',marginBottom:24}}>Start Oral Viva Room</div>
        <div className="card" style={{textAlign:'left'}}>
          <div className="form-group"><label className="form-label">Session Title *</label><input className="form-input" value={title} onChange={function(e){setTitle(e.target.value);}} placeholder="e.g. CS Final Viva"/></div>
          <div className="form-group"><label className="form-label">Topic</label><input className="form-input" value={topic} onChange={function(e){setTopic(e.target.value);}} placeholder="e.g. Data Structures"/></div>
          <div style={{padding:'10px 14px',background:'rgba(124,58,237,.1)',border:'1px solid rgba(124,58,237,.25)',borderRadius:8,marginBottom:16,fontSize:'0.82rem',color:'#a78bfa'}}>
            🎤 This is an <strong>oral viva</strong>. Questions are read aloud by TTS. Student answers are captured by speech recognition and auto-transcribed. Marks are auto-generated by Groq AI.
          </div>
          {!srSupport&&<div style={{padding:'8px 12px',background:'rgba(220,38,38,.1)',borderRadius:7,fontSize:'0.8rem',color:'#f87171',marginBottom:12}}>⚠️ Speech recognition needs Chrome/Edge. Other browsers can type answers manually.</div>}
          <button className="btn btn-primary btn-lg" style={{width:'100%',justifyContent:'center'}} onClick={handleStartRoom} disabled={loading||!title.trim()}>{loading?'Creating…':'🚀 Start Viva Room'}</button>
        </div>
      </div>
    </div>
  );

  // ════ AWAY ══════════════════════════════════════════════════
  if (examinerAway && phase==='room') {
    var am=Math.floor(awayCountdown/60), as2=awayCountdown%60;
    return (
      <div style={{minHeight:'calc(100vh - 60px)',display:'flex',alignItems:'center',justifyContent:'center',flexDirection:'column',background:'#0d0d14'}}>
        <div style={{fontSize:'3rem',marginBottom:14}}>⏸</div>
        <div style={{fontFamily:'Space Grotesk,sans-serif',fontWeight:800,fontSize:'1.5rem',color:'#fff',marginBottom:6}}>You Left the Viva Room</div>
        <div style={{fontFamily:'JetBrains Mono,monospace',fontSize:'3.5rem',fontWeight:900,color:awayCountdown<120?'#dc2626':'#f59e0b',letterSpacing:5}}>{String(am).padStart(2,'0')}:{String(as2).padStart(2,'0')}</div>
        <div style={{fontSize:'0.82rem',color:'#6b7280',marginTop:8,marginBottom:28}}>Return within 10 min or session ends</div>
        <button className="btn btn-primary btn-lg" onClick={examinerReturn}>▶ Return to Viva Room</button>
      </div>
    );
  }
  if (examinerLocked) return (
    <div style={{minHeight:'calc(100vh - 60px)',display:'flex',alignItems:'center',justifyContent:'center',flexDirection:'column',background:'#0d0d14',padding:24}}>
      <div style={{textAlign:'center',background:'rgba(220,38,38,.06)',border:'1px solid rgba(220,38,38,.2)',borderRadius:20,padding:'44px 52px',maxWidth:460}}>
        <div style={{fontSize:'3.5rem',marginBottom:14}}>🔒</div>
        <div style={{fontFamily:'Space Grotesk,sans-serif',fontWeight:800,fontSize:'1.4rem',color:'#fff',marginBottom:8}}>Session Expired</div>
        <div style={{color:'#9ca3af',marginBottom:28}}>You were away for 10+ minutes. Session terminated.</div>
        <button className="btn btn-outline" onClick={resetAll}>Start New Session</button>
      </div>
    </div>
  );

  // ════ GRADING ═══════════════════════════════════════════════
  if (phase==='grading') return (
    <div className="viva-dark" style={{display:'flex',alignItems:'center',justifyContent:'center',minHeight:'calc(100vh - 60px)',flexDirection:'column',gap:16}}>
      <div className="spinner" style={{width:52,height:52,borderWidth:4}}/>
      <div style={{color:'#a78bfa',fontWeight:700,fontSize:'1.15rem'}}>Groq AI grading {transcript.length} oral answers…</div>
      <div style={{color:'#9ca3af',fontSize:'0.85rem'}}>Matching spoken answers to model answers, generating marks</div>
    </div>
  );

  // ════ RESULTS ═══════════════════════════════════════════════
  if (phase==='results' && results) {
    var totalNow=editableAnswers.length>0?Math.round(editableAnswers.reduce(function(a,e){return a+(Number(e.score_pct)||0);},0)/editableAnswers.length):0;
    var gradeNow=totalNow>=90?'A+':totalNow>=80?'A':totalNow>=70?'B':totalNow>=60?'C':totalNow>=50?'D':'F';
    var gc2=gradeNow==='A'||gradeNow==='A+'?'#16a34a':gradeNow==='F'?'#dc2626':gradeNow==='B'?'#2563eb':'#d97706';
    return (
      <div className="fade-up">
        <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:20,flexWrap:'wrap',gap:12}}>
          <div><div className="page-title">📊 Oral Viva Results — Review &amp; Edit</div><div style={{fontSize:'0.82rem',color:'var(--text3)',marginTop:3}}>Speech-to-text answers graded by Groq. Adjust if needed, then Finalize.</div></div>
          <button className="btn btn-success" onClick={handleFinalize} disabled={finalizing}>{finalizing?'Saving…':'✅ Finalize & Save'}</button>
        </div>

        {/* Score card */}
        <div className="card" style={{marginBottom:20,borderLeft:'4px solid '+gc2}}>
          <div style={{display:'flex',alignItems:'center',gap:24,flexWrap:'wrap'}}>
            <div style={{textAlign:'center'}}><div style={{fontFamily:'Space Grotesk,sans-serif',fontWeight:900,fontSize:'3.5rem',color:gc2,lineHeight:1}}>{totalNow}%</div><div style={{fontSize:'0.72rem',color:'var(--text3)'}}>SCORE</div></div>
            <div style={{textAlign:'center'}}><div style={{fontFamily:'Space Grotesk,sans-serif',fontWeight:900,fontSize:'2.5rem',color:gc2}}>{gradeNow}</div><div style={{fontSize:'0.72rem',color:'var(--text3)'}}>GRADE</div></div>
            <div style={{textAlign:'center'}}><div style={{fontWeight:700,fontSize:'1.5rem',color:'#16a34a'}}>{editableAnswers.filter(function(e){return e.correct;}).length}</div><div style={{fontSize:'0.72rem',color:'var(--text3)'}}>CORRECT</div></div>
            <div style={{textAlign:'center'}}><div style={{fontWeight:700,fontSize:'1.5rem',color:'#dc2626'}}>{editableAnswers.filter(function(e){return !e.correct;}).length}</div><div style={{fontSize:'0.72rem',color:'var(--text3)'}}>INCORRECT</div></div>
            <div style={{flex:1,minWidth:200}}>
              <div style={{height:10,background:'var(--surface3)',borderRadius:5,overflow:'hidden'}}><div style={{height:'100%',width:totalNow+'%',background:gc2,borderRadius:5,transition:'width .4s'}}/></div>
              <div style={{fontSize:'0.72rem',color:'var(--text3)',marginTop:5}}>{title}</div>
            </div>
          </div>
        </div>

        {results.overall_feedback&&<div className="card" style={{marginBottom:20,background:'var(--accent-glow)',borderColor:'var(--accent-light)'}}><div style={{fontSize:'0.72rem',fontWeight:700,color:'var(--accent)',letterSpacing:1,marginBottom:8,fontFamily:'JetBrains Mono,monospace'}}>AI OVERALL FEEDBACK</div><div style={{fontSize:'0.9rem',lineHeight:1.7,color:'var(--text2)'}}>{results.overall_feedback}</div></div>}

        {editableAnswers.map(function(entry,i){
          var col=entry.correct?'#16a34a':entry.verdict==='Partially Correct'?'#d97706':'#dc2626';
          return (
            <div key={i} className="card" style={{marginBottom:16,borderLeft:'4px solid '+col}}>
              <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',marginBottom:14,flexWrap:'wrap',gap:10}}>
                <div style={{flex:1}}>
                  <div style={{display:'flex',gap:8,marginBottom:7,flexWrap:'wrap',alignItems:'center'}}>
                    <span className="badge badge-primary" style={{fontSize:'0.7rem'}}>Q{i+1}</span>
                    {entry._custom&&<span className="badge badge-warning" style={{fontSize:'0.7rem'}}>✏ Examiner's Q</span>}
                    <span style={{fontWeight:700,fontSize:'0.95rem'}}>{entry.question}</span>
                  </div>
                  <div style={{padding:'7px 12px',background:'var(--surface2)',borderRadius:7,fontSize:'0.82rem',color:'var(--text3)',marginBottom:8}}><strong>Model Answer:</strong> {entry.model_answer}</div>
                  <div style={{padding:'7px 12px',background:'var(--surface)',border:'1px solid var(--border)',borderRadius:7,fontSize:'0.85rem',color:'var(--text2)',marginBottom:entry.missing&&entry.missing!=='None'?8:0}}>
                    <strong>🎤 Student said:</strong> <em>{entry.student_answer||'(No answer recorded)'}</em>
                  </div>
                  {entry.missing&&entry.missing!=='None'&&<div style={{padding:'5px 10px',background:'rgba(217,119,6,.08)',border:'1px solid rgba(217,119,6,.2)',borderRadius:6,fontSize:'0.8rem',color:'#d97706',marginTop:6}}>⚠ Missing: {entry.missing}</div>}
                </div>
                <div style={{textAlign:'center',minWidth:70}}><div style={{fontWeight:900,fontSize:'1.8rem',color:col,lineHeight:1}}>{entry.score_pct}%</div><div style={{fontSize:'0.68rem',color:'var(--text3)'}}>Score</div></div>
              </div>
              <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:12,marginBottom:12}}>
                <div><label style={{display:'block',fontSize:'0.72rem',fontWeight:700,color:'var(--text3)',marginBottom:5,textTransform:'uppercase',letterSpacing:1,fontFamily:'JetBrains Mono,monospace'}}>VERDICT</label>
                  <select className="form-select" value={entry.verdict} onChange={function(e){updateAnswer(i,'verdict',e.target.value);}}>
                    <option value="Correct">✅ Correct</option><option value="Partially Correct">⚠️ Partially Correct</option>
                    <option value="Incorrect">❌ Incorrect</option><option value="No Answer">— No Answer</option>
                  </select></div>
                <div><label style={{display:'block',fontSize:'0.72rem',fontWeight:700,color:'var(--text3)',marginBottom:5,textTransform:'uppercase',letterSpacing:1,fontFamily:'JetBrains Mono,monospace'}}>SCORE (0–100)</label>
                  <input type="number" className="form-input" min={0} max={100} value={entry.score_pct} onChange={function(e){updateAnswer(i,'score_pct',Math.max(0,Math.min(100,Number(e.target.value))));}} /></div>
              </div>
              <div style={{marginBottom:10}}><label style={{display:'block',fontSize:'0.72rem',fontWeight:700,color:'var(--text3)',marginBottom:5,textTransform:'uppercase',letterSpacing:1,fontFamily:'JetBrains Mono,monospace'}}>FEEDBACK (editable)</label>
                <textarea className="form-textarea" rows={2} value={entry.feedback} onChange={function(e){updateAnswer(i,'feedback',e.target.value);}} placeholder="Edit AI feedback…"/></div>
              <div><label style={{display:'block',fontSize:'0.72rem',fontWeight:700,color:'var(--accent)',marginBottom:5,textTransform:'uppercase',letterSpacing:1,fontFamily:'JetBrains Mono,monospace'}}>EXAMINER NOTES</label>
                <textarea className="form-textarea" rows={2} value={entry.notes} onChange={function(e){updateAnswer(i,'notes',e.target.value);}} placeholder="Private notes…" style={{borderColor:'var(--accent-light)'}}/></div>
            </div>
          );
        })}
        <div style={{position:'sticky',bottom:20,textAlign:'center',marginTop:20}}>
          <button className="btn btn-success btn-lg" onClick={handleFinalize} disabled={finalizing}>{finalizing?'Saving…':'✅ Finalize & Save Results'}</button>
        </div>
      </div>
    );
  }

  // ════ FINAL ═════════════════════════════════════════════════
  if (phase==='final'&&results) {
    var fg=results.grade==='A'||results.grade==='A+'?'#16a34a':results.grade==='F'?'#dc2626':results.grade==='B'?'#2563eb':'#d97706';
    return (
      <div className="fade-up">
        <div style={{display:'flex',alignItems:'center',gap:12,marginBottom:24}}><div className="page-title">✅ Oral Viva Results Saved</div><span className="badge badge-success" style={{marginLeft:'auto'}}>Finalized</span></div>
        <div className="card" style={{marginBottom:20,textAlign:'center',padding:32,borderLeft:'4px solid '+fg}}>
          <div style={{fontFamily:'Space Grotesk,sans-serif',fontWeight:900,fontSize:'4rem',color:fg,lineHeight:1}}>{results.total_score||0}%</div>
          <div style={{fontFamily:'Space Grotesk,sans-serif',fontWeight:800,fontSize:'2rem',color:fg,marginTop:6}}>Grade {results.grade}</div>
          <div style={{display:'flex',gap:32,justifyContent:'center',marginTop:20}}>
            <div><div style={{fontWeight:700,fontSize:'1.3rem',color:'#16a34a'}}>{results.correct_count||0}</div><div style={{fontSize:'0.78rem',color:'var(--text3)'}}>Correct</div></div>
            <div><div style={{fontWeight:700,fontSize:'1.3rem',color:'#dc2626'}}>{(editableAnswers.length-(results.correct_count||0))}</div><div style={{fontSize:'0.78rem',color:'var(--text3)'}}>Incorrect</div></div>
            <div><div style={{fontWeight:700,fontSize:'1.3rem',color:'var(--accent)'}}>{editableAnswers.length}</div><div style={{fontSize:'0.78rem',color:'var(--text3)'}}>Questions</div></div>
          </div>
        </div>
        <div style={{display:'flex',gap:12}}><button className="btn btn-outline" onClick={function(){setPhase('results');}}>← Edit Results</button><button className="btn btn-primary" onClick={resetAll}>🔄 New Session</button></div>
      </div>
    );
  }

  // ════ ROOM ══════════════════════════════════════════════════
  var vivaId = savedVivaRef.current ? savedVivaRef.current.viva_id : '';
  var currentAnswer = capturedAnswer + (liveTranscript ? (capturedAnswer?' ':'')+liveTranscript : '');
  var q = questions[currentQ];

  return (
    <div className="viva-dark fade-up">
      {/* Top bar */}
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:14,flexWrap:'wrap',gap:10}}>
        <div style={{display:'flex',gap:10,alignItems:'center',flexWrap:'wrap'}}>
          <span className="badge badge-danger">🔴 ORAL VIVA LIVE</span>
          <span style={{fontWeight:700,color:'#fff'}}>{title}</span>
          {topic&&<span className="badge badge-primary" style={{fontSize:'0.68rem'}}>{topic}</span>}
          <span style={{fontFamily:'JetBrains Mono,monospace',fontSize:'0.72rem',color:'#9ca3af'}}>{transcript.length}/{questions.length} done</span>
        </div>
        <div style={{display:'flex',gap:8,flexWrap:'wrap'}}>
          <button className="btn btn-sm" style={{background:'rgba(255,255,255,.08)',color:'#e5e5e5',fontFamily:'JetBrains Mono,monospace',fontSize:'0.72rem'}} onClick={copyRoomId}>🔑 {vivaId.slice(0,8)}…</button>
          <button className="btn btn-sm" style={{background:unread>0?'rgba(220,38,38,.2)':'rgba(255,255,255,.08)',color:unread>0?'#f87171':'#e5e5e5',position:'relative'}} onClick={function(){setShowAlerts(!showAlerts);setUnread(0);}}>
            🔔{unread>0&&<span style={{position:'absolute',top:-4,right:-4,width:16,height:16,borderRadius:'50%',background:'#dc2626',color:'#fff',fontSize:'0.62rem',display:'flex',alignItems:'center',justifyContent:'center',fontWeight:700}}>{unread}</span>}
          </button>
          <button className="btn btn-sm btn-outline" onClick={function(){setShowInvite(!showInvite);if(!showInvite)loadStudents();}}>✉ Invite</button>
          <button className="btn btn-danger btn-sm" onClick={handleEndGrade} disabled={loading||transcript.length===0}>⏹ End &amp; Grade</button>
        </div>
      </div>

      {/* Alerts */}
      {showAlerts&&(<div className="card" style={{marginBottom:12,maxHeight:180,overflowY:'auto'}}>
        <div style={{fontSize:'0.7rem',fontWeight:700,color:'#9ca3af',letterSpacing:1,marginBottom:8,fontFamily:'JetBrains Mono,monospace'}}>STUDENT ACTIVITY</div>
        {alerts.length===0?<div style={{fontSize:'0.82rem',color:'#6b7280',textAlign:'center',padding:'8px 0'}}>No alerts yet…</div>
          :alerts.map(function(a,i){var col=a.type==='urgent'?'#dc2626':a.type==='success'?'#16a34a':'#d97706';return<div key={i} style={{padding:'6px 8px',borderBottom:'1px solid rgba(255,255,255,.05)',borderLeft:'3px solid '+col,marginBottom:2}}><div style={{fontWeight:700,fontSize:'0.76rem',color:col}}>{a.title}</div><div style={{fontSize:'0.72rem',color:'#9ca3af'}}>{a.message}</div></div>;})}
      </div>)}

      {/* Invite */}
      {showInvite&&(<div className="card" style={{marginBottom:12}}>
        <div style={{display:'flex',gap:8,marginBottom:10}}>{['account','email'].map(function(m){return<button key={m} onClick={function(){setInviteMode(m);}} className={'btn btn-sm '+(inviteMode===m?'btn-primary':'btn-outline')}>{m==='account'?'By Account':'By Email'}</button>;})}</div>
        {inviteMode==='account'?(<div><div style={{maxHeight:100,overflowY:'auto',display:'flex',flexWrap:'wrap',gap:6,marginBottom:8}}>{students.map(function(s){var sel=selectedStu.includes(s.user_id);return<div key={s.user_id} onClick={function(){toggleStudent(s.user_id);}} style={{padding:'4px 10px',borderRadius:20,border:'1.5px solid '+(sel?'var(--accent)':'rgba(255,255,255,.12)'),background:sel?'rgba(124,58,237,.2)':'transparent',color:sel?'#a78bfa':'#9ca3af',fontSize:'0.76rem',cursor:'pointer'}}>{s.name}</div>;})}</div>{selectedStu.length>0&&<button className="btn btn-primary btn-sm" onClick={sendInvites} disabled={inviting}>{inviting?'…':'Send to '+selectedStu.length}</button>}</div>):(<div style={{display:'flex',gap:8}}><input className="form-input" value={inviteEmail} onChange={function(e){setInviteEmail(e.target.value);}} placeholder="email1, email2…" style={{flex:1}}/><button className="btn btn-primary btn-sm" onClick={sendInvites} disabled={inviting||!inviteEmail.trim()}>{inviting?'…':'Send'}</button></div>)}
        {inviteMsg&&<div style={{marginTop:6,fontSize:'0.76rem',color:inviteMsg.startsWith('Error')?'#f87171':'#4ade80'}}>{inviteMsg}</div>}
      </div>)}

      {/* ── 3-COLUMN LAYOUT ── */}
      <div className="viva-3col">

        {/* LEFT: cam + question generator + custom Q */}
        <div style={{display:'flex',flexDirection:'column',gap:10,overflow:'auto'}}>
          <div className="card" style={{padding:10}}>
            <video ref={adminVid} autoPlay muted playsInline style={{width:'100%',borderRadius:8,background:'#000',minHeight:120,objectFit:'cover'}}/>
            <div style={{fontSize:'0.68rem',textAlign:'center',marginTop:4,color:'#9ca3af'}}>Your Camera (Admin)</div>
          </div>

          {/* AI Generator */}
          <div className="card" style={{padding:12}}>
            <div style={{fontSize:'0.7rem',fontWeight:700,color:'#9ca3af',letterSpacing:1,marginBottom:6,fontFamily:'JetBrains Mono,monospace'}}>⚡ GENERATE QUESTIONS</div>
            <div style={{fontSize:'0.7rem',color:'#6b7280',marginBottom:7}}>Appended • no repeats</div>
            <input className="form-input" value={genTopic} onChange={function(e){setGenTopic(e.target.value);}} placeholder="Topic…" style={{marginBottom:6}}/>
            <div style={{display:'flex',gap:5,marginBottom:6}}>{[3,5,7,10].map(function(n){return<button key={n} onClick={function(){setGenCount(n);}} style={{flex:1,padding:'4px 0',borderRadius:5,border:'1px solid '+(genCount===n?'var(--accent)':'rgba(255,255,255,.12)'),background:genCount===n?'rgba(124,58,237,.25)':'transparent',color:genCount===n?'#a78bfa':'#9ca3af',fontSize:'0.76rem',fontWeight:700,cursor:'pointer'}}>{n}</button>;})}</div>
            <button className="btn btn-primary btn-sm" style={{width:'100%'}} onClick={handleGenerateQ} disabled={loading||!genTopic.trim()}>{loading?'…':'⚡ Add Questions'}</button>
          </div>

          {/* Custom Q */}
          <div className="card" style={{padding:12}}>
            <div style={{fontSize:'0.7rem',fontWeight:700,color:'#9ca3af',letterSpacing:1,marginBottom:8,fontFamily:'JetBrains Mono,monospace'}}>✏ YOUR OWN QUESTION</div>
            {!showCustomQ?<button className="btn btn-outline btn-sm" style={{width:'100%'}} onClick={function(){setShowCustomQ(true);}}>+ Add Custom Question</button>:(
              <div>
                <textarea className="form-textarea" rows={2} value={customQuestion} onChange={function(e){setCustomQuestion(e.target.value);}} placeholder="Your question…" style={{marginBottom:5}}/>
                <textarea className="form-textarea" rows={2} value={customModelAns} onChange={function(e){setCustomModelAns(e.target.value);}} placeholder="Model answer (optional — AI generates if blank)" style={{marginBottom:6}}/>
                <div style={{display:'flex',gap:6}}>
                  <button className="btn btn-success btn-sm" style={{flex:1}} onClick={handleAddCustomQuestion} disabled={!customQuestion.trim()||genModel}>{genModel?'Generating…':customModelAns.trim()?'Add':'Add + AI Answer'}</button>
                  <button className="btn btn-ghost btn-sm" onClick={function(){setShowCustomQ(false);setCustomQuestion('');setCustomModelAns('');}}>✕</button>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* MIDDLE: current Q + oral answer capture */}
        <div style={{display:'flex',flexDirection:'column',gap:10,overflow:'auto'}}>
          {q ? (
            <div className="card">
              {/* Question header */}
              <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:12,flexWrap:'wrap',gap:6}}>
                <div style={{display:'flex',gap:6,alignItems:'center'}}>
                  <span className="badge badge-primary">Q{currentQ+1}/{questions.length}</span>
                  {q._custom&&<span className="badge badge-warning" style={{fontSize:'0.65rem'}}>✏ Your Q</span>}
                </div>
                <span style={{fontSize:'0.72rem',color:'#9ca3af'}}>{transcript.length} saved</span>
              </div>

              {/* Question text + TTS button */}
              <div style={{padding:'10px 14px',background:'rgba(124,58,237,.12)',border:'1px solid rgba(124,58,237,.25)',borderRadius:9,marginBottom:10}}>
                <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',gap:10}}>
                  <div style={{fontWeight:700,fontSize:'1rem',color:'#e5e5e5',lineHeight:1.55,flex:1}}>{q.question}</div>
                  <button onClick={function(){speakQuestion(q.question);}} disabled={speaking}
                    style={{padding:'6px 12px',borderRadius:7,border:'none',background:speaking?'rgba(124,58,237,.4)':'rgba(124,58,237,.25)',color:'#a78bfa',fontWeight:700,fontSize:'0.75rem',cursor:speaking?'default':'pointer',flexShrink:0,whiteSpace:'nowrap'}}>
                    {speaking?'🔊 Speaking…':'🔊 Read Aloud'}
                  </button>
                </div>
              </div>

              {/* Model answer (examiner-only) */}
              <div style={{padding:'8px 12px',background:'rgba(22,163,74,.08)',border:'1px solid rgba(22,163,74,.15)',borderRadius:7,fontSize:'0.8rem',color:'#4ade80',marginBottom:12}}>
                <div style={{fontSize:'0.62rem',fontWeight:700,letterSpacing:1,marginBottom:4,fontFamily:'JetBrains Mono,monospace',color:'#6b7280'}}>MODEL ANSWER (Examiner Only)</div>
                {q.model_answer}
              </div>

              {/* STT Answer capture */}
              <div style={{marginBottom:10}}>
                <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:6}}>
                  <label style={{fontSize:'0.72rem',fontWeight:700,color:'#9ca3af',textTransform:'uppercase',letterSpacing:1,fontFamily:'JetBrains Mono,monospace'}}>
                    🎤 Student's Oral Answer
                    {listening&&<span style={{marginLeft:8,color:'#dc2626',animation:'pulse 1s infinite'}}>● Recording</span>}
                  </label>
                  <div style={{display:'flex',gap:6}}>
                    {srSupport&&!listening&&<button onClick={startListening} style={{padding:'4px 12px',borderRadius:6,border:'none',background:'#dc2626',color:'#fff',fontWeight:700,fontSize:'0.75rem',cursor:'pointer'}}>🎤 Listen</button>}
                    {listening&&<button onClick={stopListening} style={{padding:'4px 12px',borderRadius:6,border:'none',background:'rgba(220,38,38,.2)',color:'#f87171',fontWeight:700,fontSize:'0.75rem',cursor:'pointer',border:'1px solid #dc2626'}}>⏸ Stop</button>}
                    {currentAnswer&&<button onClick={clearAnswer} style={{padding:'4px 8px',borderRadius:6,border:'1px solid rgba(255,255,255,.15)',background:'transparent',color:'#9ca3af',fontSize:'0.72rem',cursor:'pointer'}}>🗑 Clear</button>}
                  </div>
                </div>

                {/* Live transcript box */}
                <div style={{minHeight:80,padding:'10px 12px',background:'rgba(255,255,255,.05)',border:'1.5px solid '+(listening?'#dc2626':'rgba(255,255,255,.1)'),borderRadius:8,fontSize:'0.9rem',color:'#e5e5e5',lineHeight:1.65,transition:'border-color .2s'}}>
                  {currentAnswer
                    ? <span>{currentAnswer}<span style={{color:'#6b7280',fontStyle:'italic'}}>{interimText?' '+interimText:''}</span></span>
                    : <span style={{color:'#4b5563',fontStyle:'italic'}}>{listening?'Listening… speak now':'Click Listen to start capturing student\'s answer, or type below'}</span>
                  }
                </div>

                {/* Manual fallback textarea */}
                <textarea className="form-textarea" rows={2} value={capturedAnswer}
                  onChange={function(e){ setCapturedAnswer(e.target.value); }}
                  placeholder="Or type / edit answer manually…"
                  style={{marginTop:6,fontSize:'0.85rem',background:'rgba(255,255,255,.04)',border:'1px solid rgba(255,255,255,.08)',color:'#e5e5e5'}}/>
              </div>

              {/* Examiner notes */}
              <div style={{marginBottom:10}}>
                <label style={{display:'block',fontSize:'0.72rem',fontWeight:700,color:'#9ca3af',marginBottom:4,textTransform:'uppercase',letterSpacing:1,fontFamily:'JetBrains Mono,monospace'}}>Examiner Notes (private)</label>
                <textarea className="form-textarea" rows={2} value={examinerNotes} onChange={function(e){setExaminerNotes(e.target.value);}} placeholder="Confidence, hesitation, body language…" style={{background:'rgba(255,255,255,.04)',border:'1px solid rgba(255,255,255,.08)',color:'#e5e5e5'}}/>
              </div>

              {/* Verdict display */}
              {verdict&&(
                <div style={{padding:10,background:verdict.correct?'rgba(22,163,74,.12)':'rgba(220,38,38,.12)',borderRadius:8,marginBottom:10,border:'1px solid '+(verdict.correct?'rgba(22,163,74,.3)':'rgba(220,38,38,.3)')}}>
                  <div style={{display:'flex',justifyContent:'space-between',marginBottom:4}}>
                    <span style={{fontWeight:700,color:verdict.correct?'#4ade80':'#f87171'}}>{verdict.verdict}</span>
                    <span style={{fontWeight:900,fontSize:'1.1rem',color:'#a78bfa'}}>{verdict.score_pct}%</span>
                  </div>
                  <div style={{fontSize:'0.8rem',color:'#d1d5db',marginBottom:verdict.missing&&verdict.missing!=='None'?4:0}}>{verdict.feedback}</div>
                  {verdict.missing&&verdict.missing!=='None'&&<div style={{fontSize:'0.75rem',color:'#fbbf24'}}>Missing: {verdict.missing}</div>}
                </div>
              )}

              {/* Action buttons */}
              <div style={{display:'flex',gap:8}}>
                <button className="btn btn-warning btn-sm" onClick={handleGrade} disabled={verdicting||!currentAnswer.trim()}>{verdicting?'Grading…':'⚡ Grade Answer'}</button>
                <button className="btn btn-success btn-sm" onClick={handleSaveNext} disabled={!verdict}>💾 Save &amp; Next Q</button>
              </div>
            </div>
          ) : (
            <div className="card" style={{display:'flex',alignItems:'center',justifyContent:'center',minHeight:200}}>
              <div style={{textAlign:'center',color:'#9ca3af'}}><div style={{fontSize:'2.5rem',marginBottom:10}}>🎤</div><div style={{fontWeight:600}}>Add questions using the left panel to begin</div></div>
            </div>
          )}
        </div>

        {/* RIGHT: all questions + live transcript */}
        <div style={{display:'flex',flexDirection:'column',gap:10,overflow:'auto'}}>

          {/* All questions */}
          <div className="card" style={{padding:12}}>
            <div style={{fontSize:'0.7rem',fontWeight:700,color:'#9ca3af',letterSpacing:1,marginBottom:8,fontFamily:'JetBrains Mono,monospace'}}>ALL QUESTIONS ({questions.length})</div>
            <div style={{maxHeight:200,overflowY:'auto'}}>
              {questions.length===0?<div style={{fontSize:'0.76rem',color:'#4b5563',textAlign:'center',padding:'8px 0'}}>None yet</div>
                :questions.map(function(q,i){
                  var done=i<transcript.length, isCur=i===currentQ;
                  return <div key={i} onClick={function(){if(!listening){setCurrentQ(i);clearAnswer();setVerdict(null);setExaminerNotes('');} }} style={{padding:'6px 8px',borderRadius:6,cursor:'pointer',marginBottom:2,background:isCur?'rgba(124,58,237,.18)':'transparent',fontSize:'0.74rem',color:done?'#4ade80':isCur?'#e5e5e5':'#9ca3af',borderLeft:isCur?'3px solid var(--accent)':'3px solid transparent',display:'flex',alignItems:'center',gap:5}}>
                    {q._custom&&<span style={{fontSize:'0.58rem',color:'#f59e0b',flexShrink:0}}>✏</span>}
                    <span style={{flexShrink:0}}>{done?'✓':'○'} {i+1}.</span>
                    <span style={{overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{(q.question||'').slice(0,38)}{(q.question||'').length>38?'…':''}</span>
                  </div>;
                })}
            </div>
          </div>

          {/* Live full transcript */}
          <div className="card" style={{padding:12,flex:1,overflow:'auto'}}>
            <div style={{fontSize:'0.7rem',fontWeight:700,color:'#9ca3af',letterSpacing:1,marginBottom:8,fontFamily:'JetBrains Mono,monospace'}}>📝 TRANSCRIPT ({transcript.length})</div>
            {transcript.length===0?<div style={{fontSize:'0.76rem',color:'#4b5563',textAlign:'center',padding:'8px 0'}}>Auto-generated as you progress</div>
              :transcript.map(function(t,i){
                var v=t.verdict; var col=v?(v.correct?'#4ade80':v.verdict==='Partially Correct'?'#fbbf24':'#f87171'):'#9ca3af';
                return <div key={i} style={{padding:'8px 0',borderBottom:'1px solid rgba(255,255,255,.06)'}}>
                  <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:3}}>
                    <div style={{display:'flex',gap:5,alignItems:'center'}}>
                      <span style={{fontWeight:700,fontSize:'0.76rem',color:'#e5e5e5'}}>Q{i+1}</span>
                      {t._custom&&<span style={{fontSize:'0.58rem',color:'#f59e0b'}}>✏</span>}
                    </div>
                    {v&&<span style={{fontWeight:700,fontSize:'0.74rem',color:col}}>{v.score_pct}% · {v.verdict}</span>}
                  </div>
                  <div style={{fontSize:'0.7rem',color:'#a78bfa',marginBottom:2,fontStyle:'italic'}}>Q: {(t.question||'').slice(0,45)}{(t.question||'').length>45?'…':''}</div>
                  <div style={{fontSize:'0.7rem',color:'#9ca3af'}}>A: {(t.student_answer||'(no answer)').slice(0,55)}{(t.student_answer||'').length>55?'…':''}</div>
                </div>;
              })}
          </div>
        </div>
      </div>
    </div>
  );
}
